(()=>{const CURRENT_ENTITY_STORAGE_KEY='hunk-lab-current-entity-id';const NAVIGATION_STACK_STORAGE_KEY='hunk-lab-navigation-stack';const originalFetch=window.fetch.bind(window);let outerReloadScheduled=false;window.fetch=async(...args)=>{const response=await originalFetch(...args);try{const input=args[0];const url=typeof input==='string'?input:input instanceof Request?input.url:typeof input?.url==='string'?input.url:'';if(!outerReloadScheduled&&response.ok&&/\/rest\/v1\/rpc\/create_outer_entity(?:\?|$)/.test(url)){const payload=await response.clone().json();const row=Array.isArray(payload)?payload[0]:payload;if(row&&typeof row.id==='string'&&row.id){outerReloadScheduled=true;localStorage.setItem(CURRENT_ENTITY_STORAGE_KEY,row.id);localStorage.setItem(NAVIGATION_STACK_STORAGE_KEY,'[]');window.location.reload()}}}catch(error){console.error('[Hunk Lab] outer-entity navigation hotfix failed',error)}return response};function readStack(){try{const value=JSON.parse(localStorage.getItem(NAVIGATION_STACK_STORAGE_KEY)??'[]');return Array.isArray(value)&&value.every(item=>typeof item==='string')?value:[]}catch{return[]}}function goToExistingParent(){const stack=readStack();if(stack.length===0)return false;const parentId=stack.pop();if(!parentId)return false;localStorage.setItem(NAVIGATION_STACK_STORAGE_KEY,JSON.stringify(stack));localStorage.setItem(CURRENT_ENTITY_STORAGE_KEY,parentId);window.location.reload();return true}function startOuterCreation(){const activeParentInput=document.querySelector('.parent-entity-edit');if(activeParentInput instanceof HTMLInputElement){activeParentInput.focus();return}const currentLabel=document.querySelector('.current-entity-label');const nativeOutward=document.querySelector('.direction-bar button[aria-label="Наружу"]');if(!(currentLabel instanceof HTMLElement)||!(nativeOutward instanceof HTMLButtonElement))return;currentLabel.dispatchEvent(new PointerEvent('pointerup',{bubbles:true,cancelable:true,pointerId:2147483000,pointerType:'mouse',isPrimary:true,button:0,clientX:0,clientY:0}));window.setTimeout(()=>nativeOutward.click(),0)}function handleOutward(event){event.preventDefault();event.stopPropagation();if(goToExistingParent())return;startOuterCreation()}function ensureArrow(){const screenUi=document.querySelector('.screen-ui');if(!(screenUi instanceof HTMLElement))return;if(screenUi.querySelector('.lab-outward-inline'))return;const arrow=document.createElement('button');arrow.type='button';arrow.className='lab-outward-inline reuse-trigger';arrow.setAttribute('aria-label','Наружу');arrow.textContent='←';arrow.addEventListener('click',handleOutward);screenUi.appendChild(arrow)}function boot(){ensureArrow();const root=document.getElementById('root');if(!root)return;const observer=new MutationObserver(ensureArrow);observer.observe(root,{subtree:true,childList:true})}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});else boot()})();